echo "## child vs parent rung"; PYTHONIOENCODING=utf-8 uv run --offline --no-project python - <<'EOF'
import re, pathlib, collections
dev = ["code","a feature","load-bearing","a product slice","the whole product"]
si = ["a wording","a script","a rule","the method"]
rungs = {}
for p in pathlib.Path("docs/questions").glob("q-*.md"):
    t = p.read_text(encoding="utf-8")
    m = re.match(r"# (q-[\d.]+)", t); r = re.search(r"^- \*\*rung\*\* (.*)$", t, re.M)
    if m and r: rungs[m.group(1)] = dict(re.findall(r"(development|self-improvement): ([a-z -]+?)(?:,|$)", r.group(1)))
def cmp(child, parent, ladder, order):
    c, p = child.get(ladder), parent.get(ladder)
    if c is None or p is None: return "one side has none"
    return "same" if c == p else ("child higher" if order.index(c) > order.index(p) else "child lower")
stats = {l: collections.Counter() for l in ("development","self-improvement")}
n = 0
for q, r in rungs.items():
    parent = q.rsplit(".",1)[0] if "." in q else None
    if parent and parent in rungs:
        n += 1
        stats["development"][cmp(r, rungs[parent], "development", dev)] += 1
        stats["self-improvement"][cmp(r, rungs[parent], "self-improvement", si)] += 1
print("pairs:", n)
for l, c in stats.items(): print(l, dict(c))
EOF
